/**
 * The types `save/effective-paths/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    EffectivePathsUnmappedCandidate, EffectivePathsSaveInputs, EffectivePathsSaveSettings
 * depends    src/mechanics/effective-paths/types
 * used by    src/save/effective-paths/from-save, src/save/effective-paths/index, src/save/effective-paths/settings
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import type { EffectiveEconomyConfig } from '../../mechanics/effective-paths/types'
import type { EffectiveEconomyLevels } from '../../mechanics/effective-paths/types'

// from from-save.ts

/** A candidate the save could not answer, and why — never dropped in silence. */
export interface EffectivePathsUnmappedCandidate {
  sheetName: string
  reason: string
}

export interface EffectivePathsSaveInputs {
  config: EffectiveEconomyConfig
  levels: EffectiveEconomyLevels
  /** Candidate sheet names filled from this save. */
  mapped: string[]
  unmapped: EffectivePathsUnmappedCandidate[]
}

// from settings.ts

export interface EffectivePathsSaveSettings {
  /** The furthest tier with any progress, not the tier last played. */
  highestTier: number | null
  /** The best wave reached on that tier. */
  highestWave: number | null
  /** The game speed the player is running, which scales every lab timing. */
  gameSpeed: number | null
  /**
   * Every tier's best wave, keyed by tier number.
   *
   * `highestTier` and `highestWave` are one point on this curve, and the page
   * wants the curve: `wavesByCampaignTier` is what prices a path per tier. The
   * whole array was already being read here to find the furthest tier, and then
   * discarded -- so a player who imported a save had an empty per-tier map
   * while the same player importing an IDS sheet got a full one, from data the
   * save had all along.
   *
   * Only tiers with a wave above zero, so an untouched tier stays absent rather
   * than claiming a personal best of nothing.
   */
  wavesByTier: Record<number, number>
}
